from fastapi import APIRouter, Depends, HTTPException, Request
from fastapi_cache.decorator import cache

router = APIRouter(prefix="/integrations/webhooks")

def webhook_cache_key_builder(func, namespace: str = "", request: Request = None, *args, **kwargs):
    user = kwargs.get("user")
    tenant_id = user.tenant_id if user else "unknown"
    return f"{namespace}:{request.url.path}:tenant_{tenant_id}"

@router.get("/status")
@cache(expire=60, key_builder=webhook_cache_key_builder)
async def get_webhook_integration_status(
    webhook_service: WebhookService = Depends(get_webhook_service),
    user: AuthUser = Depends(get_authenticated_user)
):
    failures = await webhook_service.get_recent_delivery_failures(user.tenant_id)
    return {
        "tenant_id": user.tenant_id,
        "total_failures": len(failures),
        "recent_failed_attempts": [
            {"target_url": f.endpoint_url, "error": f.error_message, "sample_payload": f.payload_preview}
            for f in failures[:5]
        ]
    }
